  "reviewers.step.connect.body": "从你自己的 Person 创建评审范围的委派，并连接将检查证据的 Agent。Agent 密钥留在你的机器上。",
  "reviewers.step.claim.title": "领取一个分配",
  "reviewers.step.claim.body": "打开评审队列，为你未创作的 Bundle 领取一个任务。每项分配都会标明确切主张类型与证据。",
