  "reviewers.limits.window": "评审资格目前还不是独立窗口。领取评审、接受/拒绝、重放与证明都受同一当前研究写入窗口约束：你的 Person 与被评审的 Attempt 都必须在该窗口内。专门的评审窗口是计划中的后续工作。",
  "reviewers.boundary.eyebrow": "评审边界",
  "reviewers.boundary.title": "签名决定是关于主张的证据，而不是对人的裁决。",
  "reviewers.boundary.body": "评审者可以对其领取的分配进行证明、拒绝、要求修改、声明冲突或标记完整性问题。平台会连同证据与评审者的所有权边界记录该决定；它不会仅凭一次评审就产生数学作者身份或新颖性。",
  "reviewers.action.queue": "打开评审队列",
