  "proofMaps.family.verifyStep4Title": "评审并记录证据。",
  "proofMaps.family.verifyStep4Body": "命题评审、独立评审、重放与收据是各自独立的关卡；这张深度地图尚未满足其中任何一项。",
  "proofMaps.family.fillStep1Title": "抽取定理/引理命题。",
  "proofMaps.family.fillStep1Body": "把每条命题固定到论文、章节与页码；不要转述论文未陈述的依赖。",
  "proofMaps.family.fillStep2Title": "构建论证地图。",
  "proofMaps.family.fillStep2Body": "为每个定理/引理/构造添加节点，仅在证明实际使用时添加有向 `depends` 边。",
  "proofMaps.family.fillStep3Title": "对齐 Lean。",
  "proofMaps.family.fillStep3Body": "把每个节点映射到声明或 comparator 命题，或标记为 `unmapped`；有内核检查时记录工具链、Mathlib 修订与公理。",
  "proofMaps.family.fillStep4Title": "添加跨 solution 关系。",
  "proofMaps.family.fillStep4Body": "只有在评审后才使用 `same-role`、`replaces` 与 `bypasses`；绝不要把共享角色当作逻辑等价。",
  "proofMaps.family.fillStep5Title": "评审并记录证据。",
  "proofMaps.family.fillStep5Body": "独立评审、重放与收据是各自独立的关卡；骨架或草稿不满足它们。",
  "proofMaps.family.leanStep1Title": "阅读论文的证明主线。",
  "proofMaps.family.leanStep1Body": "派生结构只给出形式化目标、求解定理与允许公理，不包含论文如何组织或使用它们。",
  "proofMaps.family.leanStep2Title": "用有来源的依赖替换结构。",
  "proofMaps.family.leanStep2Body": "只在论文或已定位声明明确写出处添加引理级节点与有向边，并删除证明未使用的机制。",
  "proofMaps.family.leanStep3Title": "对齐声明并开启评审。",
